package com.northstar.banking.configuration;

import java.util.Set;
import io.swagger.v3.oas.models.Components;
import io.swagger.v3.oas.models.OpenAPI;
import io.swagger.v3.oas.models.Operation;
import io.swagger.v3.oas.models.PathItem;
import io.swagger.v3.oas.models.info.Info;
import io.swagger.v3.oas.models.media.StringSchema;
import io.swagger.v3.oas.models.parameters.HeaderParameter;
import io.swagger.v3.oas.models.responses.ApiResponse;
import io.swagger.v3.oas.models.responses.ApiResponses;
import io.swagger.v3.oas.models.security.SecurityRequirement;
import io.swagger.v3.oas.models.security.SecurityScheme;
import org.springdoc.core.customizers.OpenApiCustomizer;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Adds security and logout metadata to the DTO and controller descriptions
 * generated by Springdoc. Logout runs in a security filter, outside Spring MVC.
 */
@Configuration
public class OpenApiConfiguration {
    private static final String SESSION = "customerSession";
    private static final Set<String> PUBLIC_ROUTES = Set.of(
            "/api/v1/auth/csrf", "/api/v1/auth/register", "/api/v1/auth/login");

    /** Defines API metadata and the session cookie scheme for the generated contract. */
    @Bean
    OpenAPI northstarOpenApi() {
        return new OpenAPI().info(new Info().title("Northstar Bank").version("v1")
                        .description("Simulated CAD banking API. Obtain the current CSRF token before each POST. "
                                + "Login rotates the session and invalidates the previous token."))
                .components(new Components().addSecuritySchemes(SESSION, new SecurityScheme()
                        .type(SecurityScheme.Type.APIKEY).in(SecurityScheme.In.COOKIE).name("NORTHSTAR_SESSION")));
    }

    /** Adds the filter-based logout route and annotates which operations need a session or CSRF token. */
    @Bean
    OpenApiCustomizer securityOperations() {
        return api -> {
            var responses = new ApiResponses().addApiResponse("204", new ApiResponse().description("Session ended"));
            api.path("/api/v1/auth/logout", new PathItem().post(new Operation()
                    .operationId("logout").summary("End the current session").responses(responses)));
            api.getPaths().forEach((path, item) -> {
                if (!PUBLIC_ROUTES.contains(path)) {
                    item.readOperations().forEach(operation -> operation.addSecurityItem(new SecurityRequirement().addList(SESSION)));
                }
                if (item.getPost() != null) {
                    item.getPost().addParametersItem(new HeaderParameter().name("X-CSRF-TOKEN").required(true)
                            .description("Token issued by GET /api/v1/auth/csrf.").schema(new StringSchema()));
                }
            });
        };
    }
}
